componentRules.body:
/* Primary = flat black ink. Pill shape, bold text, halo-ring hover. */
  --btn-bg: var(--ink);
  --btn-fg: #fff;
  --btn-border: var(--ink);
  --btn-halo: rgba(11, 13, 18, 0.12);     /* ink halo for ink button */
  --btn-ring: rgba(11, 13, 18, 0.20);

  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid var(--btn-border);
  background: var(--btn-bg);
  color: var(--btn-fg);
  padding: 0 22px;
  height: 46px;
  font-family: var(--font-sans);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  isolation: isolate;
  user-select: none;
  transition: background var(--dur-fast) var(--ease-out),
              border-color var(--dur-fast) var(--ease-out),
              color var(--dur-fast) var(--ease-out),
              transform var(--dur-fast) var(--ease-out),
              box-shadow var(--dur-base) var(--ease-out);

--btn-bg: transparent;
  --btn-fg: var(--ink);
  --btn-border: transparent;
  padding-left: 6px;
  padding-right: 6px;
  height: auto;
  border-radius: var(--radius-sm);
  font-weight: 600;
  overflow: visible;

content: "";
